{
  "name": "agent-voice",
  "version": "0.1.0",
  "description": "Voice agent reference (Mars + Venus personas, WebRTC-first browser client, optional Twilio adapter). Copied into the operator's host agent repo via `gbrain integrations install agent-voice`; not a runtime gbrain dependency.",
  "type": "module",
  "main": "code/server.mjs",
  "scripts": {
    "start": "node code/server.mjs",
    "test": "vitest run",
    "test:watch": "vitest",
    "test:e2e": "vitest run tests/e2e/voice-roundtrip.test.mjs",
    "test:full-flow": "vitest run tests/e2e/voice-full-flow.test.mjs",
    "gen:baselines": "node tests/evals/mars-eval.mjs --baseline && node tests/evals/venus-eval.mjs --baseline"
  },
  "dependencies": {
    "ws": "^8.16.0"
  },
  "devDependencies": {
    "puppeteer": "^23.11.1",
    "vitest": "^4.1.4"
  },
  "engines": {
    "node": ">=18.0.0"
  },
  "private": false,
  "license": "MIT"
}

{
  "comment": "Post-install assertions for the voice-agent-install scenario. Soft-fail policy on the SEMANTIC tier (LLM-judge) and on upstream-API outages; hard-fail on missing files, missing resolver rows, PII leaks, or zero audio frames.",
  "filesystem": {
    "must_exist": [
      "services/voice-agent/code/server.mjs",
      "services/voice-agent/code/lib/personas/mars.mjs",
      "services/voice-agent/code/lib/personas/venus.mjs",
      "services/voice-agent/code/lib/personas/personas.mjs",
      "services/voice-agent/code/lib/personas/private-name-blocklist.json",
      "services/voice-agent/code/lib/context-builder.example.mjs",
      "services/voice-agent/code/tools.mjs",
      "services/voice-agent/code/public/call.html",
      "services/voice-agent/.gbrain-source.json",
      "services/voice-agent/package.json",
      "skills/voice-persona-mars/SKILL.md",
      "skills/voice-persona-venus/SKILL.md",
      "skills/voice-post-call/SKILL.md"
    ]
  },
  "gbrain_source_json": {
    "recipe": "agent-voice",
    "install_kind": "copy-into-host-repo",
    "must_NOT_have_fields": ["upstream_repo", "imported_from", "source_url"],
    "min_files_count": 20,
    "files_entries_must_have": ["src", "target", "sha256", "mode"]
  },
  "resolver_rows": {
    "file": "AGENTS.md",
    "must_contain": ["voice-persona-mars", "voice-persona-venus", "voice-post-call"],
    "preserves_existing_content": true
  },
  "privacy": {
    "comment": "Specific banned-name list lives in $AGENT_VOICE_PII_BLOCKLIST env var (set by CI from a secret, or by the operator in .zshrc). Literal names deliberately NOT in this checked-in file per CLAUDE.md's 'never use private agent names in shipped artifacts.'",
    "blocklist_env_var": "AGENT_VOICE_PII_BLOCKLIST",
    "scan_paths": ["services/voice-agent/", "skills/voice-persona-mars/", "skills/voice-persona-venus/", "skills/voice-post-call/"]
  },
  "server": {
    "health_endpoint": "/health",
    "health_response": { "ok": true },
    "max_startup_seconds": 30,
    "default_port_env": "AGENT_VOICE_TEST_PORT",
    "default_port": 8766
  },
  "audio_roundtrip": {
    "blocks_ship": false,
    "tier_a_hard_fail_on": {
      "audioSendCount_eq": 0,
      "audioPlayCount_eq": 0
    },
    "tier_b_hard_fail_on": {
      "responseBlobSize_lt_bytes": 5120
    },
    "tier_c_soft_fail_only": true
  },
  "upstream_soft_fail_codes": {
    "openai_realtime_http": [429, 500, 502, 503, 504],
    "ws_close": [1011, 1013, 1006]
  }
}

/**
 * model-pricing — canonical table + canonicalLookup + the drift guard.
 *
 * Because the other pricing tables are DERIVED from CANONICAL_PRICING (not
 * hand-copied), cross-table price drift — the kind that left Opus 4.7 at
 * $15/$75 in takes-quality-eval while anthropic-pricing.ts had $5/$25
 * (gbrain#1819) — is structurally impossible. The "drift guard" below is a
 * regression trip-wire: it asserts each derived view still equals canonical, so
 * if anyone later re-hardcodes a view back into a duplicate, CI catches it. The
 * cross-modal panel check is genuinely load-bearing — it asserts canonical
 * actually carries every model the runner prices.
 */
import { describe, test, expect } from 'bun:test';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import {
  CANONICAL_PRICING,
  canonicalLookup,
} from '../src/core/model-pricing.ts';
import { ANTHROPIC_PRICING } from '../src/core/anthropic-pricing.ts';
import { MODEL_PRICING } from '../src/core/takes-quality-eval/pricing.ts';
import { estimateAnthropicCost } from '../src/core/brain-score-recommendations.ts';

describe('CANONICAL_PRICING — table integrity', () => {
  test('every entry has finite positive rates and a provider-prefixed key', () => {
    for (const [key, p] of Object.entries(CANONICAL_PRICING)) {
      expect(Number.isFinite(p.input)).toBe(true);
      expect(Number.isFinite(p.output)).toBe(true);
      expect(p.input).toBeGreaterThan(0);
      expect(p.output).toBeGreaterThan(0);
      // Provider-prefixed key (sanity guard against a bare key sneaking in).
      // NOTE: deliberately NO output>=input invariant — symmetric pricing is
      // legitimate (e.g. together:...Llama-3.3 is 0.88/0.88).
      expect(key).toContain(':');
    }
  });

  test('Opus 4.8 present at $5/$25 (closes gbrain#1819)', () => {
    expect(CANONICAL_PRICING['anthropic:claude-opus-4-8']).toEqual({ input: 5.0, output: 25.0 });
  });

  test('Opus 4.7 at $5/$25 (not the stale $15/$75)', () => {
    expect(CANONICAL_PRICING['anthropic:claude-opus-4-7']).toEqual({ input: 5.0, output: 25.0 });
  });

  test('Gemini 2.0 Flash reconciled to $0.10/$0.40; legacy alias agrees', () => {
    expect(CANONICAL_PRICING['google:gemini-2.0-flash']).toEqual({ input: 0.1, output: 0.4 });
    expect(CANONICAL_PRICING['google:gemini-2-flash']).toEqual(
      CANONICAL_PRICING['google:gemini-2.0-flash'],
    );
  });
});

describe('canonicalLookup — id normalization', () => {
  test('bare anthropic id → hit (defaults to anthropic provider)', () => {
    expect(canonicalLookup('claude-opus-4-8')).toEqual({ input: 5.0, output: 25.0 });
  });

  test('colon form → hit', () => {
    expect(canonicalLookup('anthropic:claude-opus-4-8')).toEqual({ input: 5.0, output: 25.0 });
  });

  test('slash form → hit', () => {
    expect(canonicalLookup('anthropic/claude-opus-4-8')).toEqual({ input: 5.0, output: 25.0 });
  });

  test('non-anthropic bare id → miss (preserves prior null contract)', () => {
    expect(canonicalLookup('gpt-5')).toBeUndefined();
  });

  test('nested OpenRouter id → MISS (markup ≠ native pricing)', () => {
    expect(canonicalLookup('openrouter:anthropic/claude-sonnet-4-6')).toBeUndefined();
  });

  test('slash-bearing model tail kept as exact key (together Llama)', () => {
    expect(canonicalLookup('together:meta-llama/Llama-3.3-70B-Instruct-Turbo')).toEqual({
      input: 0.88,
      output: 0.88,
    });
  });

  test('null / empty → undefined (no throw)', () => {
    expect(canonicalLookup(null)).toBeUndefined();
    expect(canonicalLookup(undefined)).toBeUndefined();
    expect(canonicalLookup('')).toBeUndefined();
  });
});

describe('DRIFT GUARD — derived views stay equal to canonical (re-hardcode trip-wire)', () => {
  test('ANTHROPIC_PRICING (bare) equals canonical anthropic: entries', () => {
    for (const [key, p] of Object.entries(CANONICAL_PRICING)) {
      if (!key.startsWith('anthropic:')) continue;
      const bare = key.slice('anthropic:'.length);
      expect(ANTHROPIC_PRICING[bare]).toEqual(p);
    }
  });

  test('takes-quality MODEL_PRICING equals canonical for every allowlisted key', () => {
    for (const [key, p] of Object.entries(MODEL_PRICING)) {
      const c = canonicalLookup(key);
      expect(c).toBeDefined();
      expect(p.input_per_1m).toBe(c!.input);
      expect(p.output_per_1m).toBe(c!.output);
    }
  });

  test('cross-modal panel models are all priced from canonical', () => {
    // The runner now calls canonicalLookup(slot.model) directly, so presence
    // here = the runner prices these. Mirrors the panel it used to inline.
    for (const id of [
      'openai:gpt-4o',
      'openai:gpt-4o-mini',
      'anthropic:claude-opus-4-7',
      'anthropic:claude-sonnet-4-6',
      'google:gemini-1.5-pro',
      'google:gemini-2.0-flash',
      'together:meta-llama/Llama-3.3-70B-Instruct-Turbo',
      'deepseek:deepseek-chat',
    ]) {
      expect(canonicalLookup(id)).toBeDefined();
    }
  });
});

describe('S1A — raw-index consumers price provider-prefixed ids', () => {
  test('estimateAnthropicCost prices anthropic:claude-opus-4-8 (was zero pre-fix)', () => {
    // 1 call, 1M in, 1M out → 1*5 + 1*25 = $30. Pre-fix the bare-key index
    // missed on the provider-prefixed id and returned 0.
    const cost = estimateAnthropicCost('anthropic:claude-opus-4-8', 1, 1_000_000, 1_000_000);
    expect(cost).toBeCloseTo(30.0, 2);
  });
});

describe('no heavy import (cycle guard)', () => {
  test('model-pricing.ts imports only model-id.ts (relative)', () => {
    const src = readFileSync(
      fileURLToPath(new URL('../src/core/model-pricing.ts', import.meta.url)),
      'utf8',
    );
    const relImports = [...src.matchAll(/^\s*import\s.*from\s+['"](\.[^'"]+)['"]/gm)].map(
      (m) => m[1],
    );
    expect(relImports).toEqual(['./model-id.ts']);
  });
});

/**
 * E2E test for PostgresEngine forward-reference bootstrap.
 *
 * Codex caught that `test/e2e/helpers.ts:74` uses the standalone
 * `db.initSchema()` from `src/core/db.ts`, which only runs SCHEMA_SQL and
 * never calls runMigrations(). A test using that helper would NOT exercise
 * `PostgresEngine.initSchema()`'s reordered path, producing false-positive
 * coverage. This test deliberately bypasses the standard helper and
 * instantiates `PostgresEngine` directly, calling `engine.initSchema()` so
 * the bootstrap → SCHEMA_SQL → runMigrations sequence runs end-to-end.
 *
 * Covers issues #366, #375, #378 — Postgres-side wedges where pre-v0.18
 * brains crashed on `column "source_id" does not exist`.
 *
 * NOTE: snapshot-based historical state simulation is out of scope for this
 * wave (would require maintaining historical schema dumps). The test
 * mutates a fresh-LATEST brain to a pre-v0.18 shape; codex flagged this as
 * approximate. Acceptable here because the bootstrap's contract is narrow:
 * "given a brain that lacks the specific forward-references, initSchema
 * produces a brain at LATEST." The test exercises exactly that contract.
 *
 * Run: DATABASE_URL=postgresql://... bun run test:e2e test/e2e/postgres-bootstrap.test.ts
 */

import { describe, test, expect, beforeAll, afterAll } from 'bun:test';
import { PostgresEngine } from '../../src/core/postgres-engine.ts';
import { LATEST_VERSION } from '../../src/core/migrate.ts';

const DATABASE_URL = process.env.DATABASE_URL;
const skip = !DATABASE_URL;

describe.skipIf(skip)('PostgresEngine forward-reference bootstrap (E2E)', () => {
  let engine: PostgresEngine;

  beforeAll(async () => {
    engine = new PostgresEngine();
    await engine.connect({ database_url: DATABASE_URL! });
  }, 30_000);

  afterAll(async () => {
    await engine.disconnect();
  });

  test('PostgresEngine.initSchema applies bootstrap → SCHEMA_SQL → migrations on pre-v0.18 brain', async () => {
    // First call: bring the test DB to LATEST shape so we have something to mutate.
    await engine.initSchema();

    // Clear data from prior tests in the suite. Adding a UNIQUE(slug)
    // constraint below would fail if multi-source fixtures left rows with
    // duplicate slugs across sources (which is valid under the composite
    // UNIQUE this test is undoing).
    const conn = (engine as any).sql;
    await conn.unsafe(`TRUNCATE pages, content_chunks, links, tags, raw_data, timeline_entries, page_versions, ingest_log RESTART IDENTITY CASCADE`);

    // Mutate to pre-v0.18 shape: drop source_id and the sources table.
    // The advisory lock is released between initSchema calls, so this
    // direct DDL won't deadlock.
    await conn.unsafe(`
      ALTER TABLE pages DROP CONSTRAINT IF EXISTS pages_source_slug_key;
      ALTER TABLE pages ADD CONSTRAINT pages_slug_key UNIQUE (slug);
      DROP INDEX IF EXISTS idx_pages_source_id;
      ALTER TABLE pages DROP COLUMN IF EXISTS source_id CASCADE;
      DROP TABLE IF EXISTS sources CASCADE;
    `);
    await engine.setConfig('version', '20');

    // The path under test: full PostgresEngine.initSchema() including the
    // bootstrap call, SCHEMA_SQL replay, and runMigrations chain.
    await engine.initSchema();

    expect(await engine.getConfig('version')).toBe(String(LATEST_VERSION));

    // Verify the forward-referenced column exists after upgrade.
    const colCheck = await conn`
      SELECT column_name FROM information_schema.columns
      WHERE table_schema = current_schema()
        AND table_name = 'pages'
        AND column_name = 'source_id'
    `;
    expect(colCheck).toHaveLength(1);

    // Verify the default source row was seeded.
    const srcCheck = await conn`SELECT id FROM sources WHERE id = 'default'`;
    expect(srcCheck).toHaveLength(1);
  });

  test('PostgresEngine.initSchema is idempotent on a brain already at LATEST', async () => {
    // Fresh-LATEST brain. Calling initSchema again must not error and must
    // not regress the version.
    await engine.initSchema();
    expect(await engine.getConfig('version')).toBe(String(LATEST_VERSION));
  });
});

/**
 * v0.41.22.2 — batch-retry-audit privacy backfill regression.
 *
 * Pins that `redactConnectionInfo` is wired into `logBatchRetry` and
 * `logBatchExhausted` (D9 privacy backfill). A future refactor that
 * removes the redactor call from `summarizeError` would silently
 * reintroduce the DSN/host/password leak class. This test catches that
 * via wire-format inspection.
 *
 * Hermetic via withEnv + tempdir per test.
 */

import { describe, expect, test, beforeEach, afterEach } from 'bun:test';
import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';
import { withEnv } from '../helpers/with-env.ts';
import {
  logBatchRetry,
  logBatchExhausted,
  BATCH_RETRY_FEATURE_NAME,
} from '../../src/core/audit/batch-retry-audit.ts';
import { computeIsoWeekFilename } from '../../src/core/audit/audit-writer.ts';

let tmpDir: string;

beforeEach(() => {
  tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'batch-retry-redact-'));
});

afterEach(() => {
  try {
    fs.rmSync(tmpDir, { recursive: true, force: true });
  } catch { /* best-effort */ }
});

describe('batch-retry-audit privacy backfill (D9)', () => {
  test('case 1 — logBatchRetry: PG connection-failure error has no DSN/IP/password in JSONL', async () => {
    await withEnv({ GBRAIN_AUDIT_DIR: tmpDir }, async () => {
      const err = new Error(
        'PG retry context: postgres://garry:hunter2@db.example.com:5432/gbrain failed (192.168.1.42)',
      );
      logBatchRetry('addLinksBatch', 100, 1, 1000, err);
      const file = path.join(tmpDir, computeIsoWeekFilename(BATCH_RETRY_FEATURE_NAME));
      const raw = fs.readFileSync(file, 'utf8');
      expect(raw).not.toContain('hunter2');
      expect(raw).not.toContain('192.168.1.42');
      expect(raw).not.toContain('postgres://garry');
      expect(raw).toContain('<REDACTED:pg_url>');
      expect(raw).toContain('<REDACTED:ipv4>');
    });
  });

  test('case 2 — logBatchExhausted: same privacy contract on the exhausted path', async () => {
    await withEnv({ GBRAIN_AUDIT_DIR: tmpDir }, async () => {
      const err = new Error('FATAL: password=hunter2 authentication failed for user=postgres');
      logBatchExhausted('addTimelineEntriesBatch', 50, 4, err);
      const file = path.join(tmpDir, computeIsoWeekFilename(BATCH_RETRY_FEATURE_NAME));
      const raw = fs.readFileSync(file, 'utf8');
      expect(raw).not.toContain('hunter2');
      expect(raw).toContain('<REDACTED:password>');
      expect(raw).toContain('<REDACTED:user>');
    });
  });

  test('case 3 — plain error message (no secrets) flows through unchanged', async () => {
    await withEnv({ GBRAIN_AUDIT_DIR: tmpDir }, async () => {
      logBatchRetry('upsertChunks', 100, 1, 1000, new Error('Connection terminated unexpectedly'));
      const file = path.join(tmpDir, computeIsoWeekFilename(BATCH_RETRY_FEATURE_NAME));
      const raw = fs.readFileSync(file, 'utf8');
      expect(raw).toContain('Connection terminated unexpectedly');
      expect(raw).not.toContain('<REDACTED');
    });
  });
});

/**
 * ci-cache-hash.test.ts — adversarial coverage of the auto-cache hash.
 *
 * The cache key controls false-pass risk. If a test-affecting file is
 * accidentally deny-listed (or a file change fails to invalidate the
 * hash), broken code ships under a green CI check. This suite is the
 * primary safety net.
 *
 * Strategy: each test spins up a synthetic git repo, copies the
 * ci-cache-hash.sh script in, populates a small file set covering the
 * deny-list edges, runs the script, modifies one file, runs again,
 * asserts hash behavior.
 *
 * Critical invariants (the false-pass guards):
 *   - CLAUDE.md edit → DIFFERENT hash
 *   - AGENTS.md edit → DIFFERENT hash
 *   - skills/foo/SKILL.md edit → DIFFERENT hash
 *   - src/core/db.ts edit → DIFFERENT hash
 *   - test/foo.test.ts edit → DIFFERENT hash
 *
 * Safe deny-list invariants:
 *   - CHANGELOG.md edit → same hash
 *   - README.md edit → same hash
 *   - docs/guide.md edit → same hash
 *   - TODOS.md edit → same hash
 *   - LICENSE edit → same hash
 */

import { afterAll, beforeAll, describe, expect, it } from "bun:test";
import { execFileSync, spawnSync } from "node:child_process";
import {
  cpSync,
  mkdirSync,
  mkdtempSync,
  rmSync,
  symlinkSync,
  writeFileSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { join, resolve } from "node:path";

const REPO_ROOT = resolve(import.meta.dir, "..", "..");
const SCRIPT_SRC = resolve(REPO_ROOT, "scripts/ci-cache-hash.sh");

interface Sandbox {
  dir: string;
  scriptPath: string;
}

function makeSandbox(files: Record<string, string>): Sandbox {
  const dir = mkdtempSync(join(tmpdir(), "ci-cache-hash-"));
  // Init git repo
  execFileSync("git", ["init", "--quiet"], { cwd: dir });
  execFileSync("git", ["config", "user.email", "test@example.com"], { cwd: dir });
  execFileSync("git", ["config", "user.name", "Test"], { cwd: dir });

  // Copy script under scripts/ so cd "$(dirname "$0")/.." lands at sandbox root
  mkdirSync(join(dir, "scripts"), { recursive: true });
  cpSync(SCRIPT_SRC, join(dir, "scripts/ci-cache-hash.sh"));

  // Write each fixture file under its declared path
  for (const [path, content] of Object.entries(files)) {
    const abs = join(dir, path);
    mkdirSync(resolve(abs, ".."), { recursive: true });
    writeFileSync(abs, content);
  }

  // Stage + commit so git ls-files returns them
  execFileSync("git", ["add", "-A"], { cwd: dir });
  execFileSync("git", ["commit", "--quiet", "-m", "fixture"], { cwd: dir });

  return { dir, scriptPath: join(dir, "scripts/ci-cache-hash.sh") };
}

function hash(s: Sandbox): string {
  const r = spawnSync("bash", [s.scriptPath], {
    cwd: s.dir,
    encoding: "utf8",
  });
  if (r.status !== 0) {
    throw new Error(`ci-cache-hash exit ${r.status}: ${r.stderr}`);
  }
  return r.stdout.trim();
}

function modify(s: Sandbox, path: string, content: string) {
  writeFileSync(join(s.dir, path), content);
  // The script reads `git ls-files -s` which reflects the INDEX, not
  // the working tree. Stage + commit so the change is visible to the
  // hash. This matches what CI sees on a checked-out PR (committed
  // tree, not working tree).
  execFileSync("git", ["add", path], { cwd: s.dir });
  execFileSync("git", ["commit", "--quiet", "-m", `modify ${path}`], {
    cwd: s.dir,
  });
}

// ──────────────────────────────────────────────────────────────────────
// Baseline fixtures used across most cases.
// ──────────────────────────────────────────────────────────────────────
const BASELINE_FILES: Record<string, string> = {
  "CHANGELOG.md": "# Changelog\n\n## [1.0.0]\n",
  "TODOS.md": "- [ ] thing\n",
  "README.md": "# Project\n",
  "LICENSE": "MIT\n",
  "CLAUDE.md": "# CLAUDE.md\n\nproject instructions\n",
  "AGENTS.md": "# AGENTS.md\n\nopenclaw entry\n",
  "package.json": '{"name":"test","version":"0.0.0"}\n',
  "bun.lock": "lockfile-v1\n",
  "tsconfig.json": '{"compilerOptions":{"strict":true}}\n',
  "src/core/db.ts": "export const db = 1;\n",
  "src/cli.ts": "console.log('hi');\n",
  "test/foo.test.ts": "import {test} from 'bun:test';\ntest('x', () => {});\n",
  "scripts/check-x.sh": "#!/bin/bash\necho ok\n",
  ".github/workflows/test.yml": "name: Test\n",
  "skills/foo/SKILL.md": "---\nname: foo\n---\nFoo skill\n",
  "docs/guide.md": "# Guide\n",
  "docs/sub/notes.md": "Notes\n",
  "docs/raw.txt": "raw text\n",
};

describe("ci-cache-hash.sh — determinism", () => {
  let sb: Sandbox;
  beforeAll(() => {
    sb = makeSandbox(BASELINE_FILES);
  });
  afterAll(() => {
    if (sb) rmSync(sb.dir, { recursive: true, force: true });
  });

  it("same tree → same hash (run twice)", () => {
    const h1 = hash(sb);
    const h2 = hash(sb);
    expect(h1).toBe(h2);
    expect(h1).toMatch(/^[0-9a-f]{16}$/);
  });

  it("hash is 16-char lowercase hex", () => {
    const h = hash(sb);
    expect(h).toMatch(/^[0-9a-f]{16}$/);
  });
});

describe("ci-cache-hash.sh — CRITICAL false-pass guards (must invalidate)", () => {
  // Each test gets its own sandbox so modifications don't leak across cases.

  function withSandbox(test: (sb: Sandbox) => void) {
    const sb = makeSandbox(BASELINE_FILES);
    try {
      test(sb);
    } finally {
      rmSync(sb.dir, { recursive: true, force: true });
    }
  }

  it("CLAUDE.md edit MUST change hash (8+ test files reference it)", () => {
    withSandbox((sb) => {
      const before = hash(sb);
      modify(sb, "CLAUDE.md", "# CLAUDE.md\n\nNEW INSTRUCTIONS\n");
      const after = hash(sb);
      expect(after).not.toBe(before);
    });
  });

  it("AGENTS.md edit MUST change hash (resolver tests read it)", () => {
    withSandbox((sb) => {
      const before = hash(sb);
      modify(sb, "AGENTS.md", "# AGENTS.md\n\nNEW DISPATCH\n");
      const after = hash(sb);
      expect(after).not.toBe(before);
    });
  });

  it("skills/foo/SKILL.md edit MUST change hash (skill conformance tests)", () => {
    withSandbox((sb) => {
      const before = hash(sb);
      modify(sb, "skills/foo/SKILL.md", "---\nname: foo\n---\nNEW SKILL BODY\n");
      const after = hash(sb);
      expect(after).not.toBe(before);
    });
  });

  it("src/core/db.ts edit MUST change hash", () => {
    withSandbox((sb) => {
      const before = hash(sb);
      modify(sb, "src/core/db.ts", "export const db = 2;\n");
      const after = hash(sb);
